Current task: fix Load failed (iframe cannot execute bundle).
You fixed backend + wiring.

Now failure is inside iframe execution layer.

🔴 Root cause
Your bundle contains:
JavaScriptrequire(...)
Because of:
JavaScriptexternal: ["react", "react-dom", "next/*"]
👉 esbuild leaves imports unresolved

👉 Browser (iframe) has NO require → crash → Load failed

✅ Fix (make bundle browser-safe)
👉 You must NOT externalize react/react-dom

🔥 Bash fix (full overwrite runner)
Bashcat > runtime/node/esbuild-runner.cjs <<'EOF'
const esbuild = require("esbuild");
const fs = require("fs");
const path = require("path");

(async () => {
  try {
    const projectId = process.argv[2];

    const projectRoot = path.join(
      process.cwd(),
      "runtime/workspaces/default/projects",
      projectId
    );

    const entry = path.join(projectRoot, "app/page.tsx");

    if (!fs.existsSync(entry)) {
      throw new Error("Entry not found: " + entry);
    }

    const tempEntry = path.join(projectRoot, "__preview-entry.tsx");

    fs.writeFileSync(
      tempEntry,
      `
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app/page";

const root = document.getElementById("root");

if (!root) throw new Error("Missing #root");

ReactDOM.createRoot(root).render(
  React.createElement(App)
);
`
    );

    const result = await esbuild.build({
      entryPoints: [tempEntry],
      bundle: true,
      write: false,
      platform: "browser",
      format: "iife",
      jsx: "automatic",
      loader: {
        ".ts": "ts",
        ".tsx": "tsx",
        ".css": "empty",
      },
      // ❌ REMOVE react externalization
      external: [
        "next/*" // only this stays
      ],
    });

    fs.unlinkSync(tempEntry);

    process.stdout.write(result.outputFiles[0].text);

  } catch (err) {
    console.error("BUILD_ERROR_START");
    console.error(err);
    console.error("BUILD_ERROR_END");
    process.exit(1);
  }
})();
EOF

rm -rf .next
npm run dev

